import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import AsyncStorage from '@react-native-async-storage/async-storage';
import NetInfo from '@react-native-community/netinfo';
import * as ImagePicker from 'expo-image-picker';
import * as Notifications from 'expo-notifications';
import { Alert, Image, Modal, Platform, Pressable, SafeAreaView, ScrollView, Share, StatusBar, StyleSheet, Switch, Text, TextInput, View } from 'react-native';
import RouteScreen from './src/RouteScreen';
import { BootstrapData, CustomerRow, NotificationRow, Session, VehicleRow, loadBootstrap, markNotificationRead, refreshSession, signIn } from './src/api';
import { LocalAppointment, LocalKmRecord, LocalState, SyncDiagnostics, SyncReport, enqueue, enqueueReplacingLocal, readLastSyncReport, readLocalState, readQueue, readSyncDiagnostics, removeAppointmentLocal, removeQueuedForLocal, saveAppointmentLocal, saveKmLocal, syncPending } from './src/offline';
import { DEFAULT_ENTERPRISE_SETTINGS, EnterpriseSettings, readEnterpriseSettings } from './src/adminSettings';
import TripPlannerScreen, { PlannedTrip } from './src/TripPlannerScreen';
import ExpensesScreen from './src/ExpensesScreen';
import { readExpenses, summarizeExpenses } from './src/expenses';
import DatePickerField from './src/DatePickerField';

type Tab = 'home' | 'agenda' | 'km' | 'mapa' | 'mais';
type MorePage = 'menu' | 'lojas' | 'relatorios' | 'despesas' | 'notificacoes' | 'sincronizacao' | 'configuracoes';
type Appointment = { id: string; date: string; time: string; title: string; store: string; type: string; customerId?: string; local?: boolean; status?: string; travel?: LocalAppointment['travel']; routeStatus?: LocalAppointment['routeStatus']; routeStatusAt?: string };
type Preferences = { autoSync: boolean; offlineMode: boolean; notifications: boolean };

const BLUE = '#1769E0';
const NAVY = '#0B3558';
const BG = '#F3F6FA';
const TEXT = '#17324D';
const MUTED = '#78889A';
const BORDER = '#DFE6EE';
const GREEN = '#22B77A';
const ORANGE = '#F59E0B';
const RED = '#E5484D';
const SESSION_KEY = 'movvant.rc11.session';
const PREFS_KEY = 'movvant.rc11.preferences';
const MONTHS = ['Janeiro','Fevereiro','Março','Abril','Maio','Junho','Julho','Agosto','Setembro','Outubro','Novembro','Dezembro'];
const WEEK = ['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'];
const DEFAULT_PREFS: Preferences = { autoSync: true, offlineMode: true, notifications: true };

const pad = (n: number) => String(n).padStart(2, '0');
const isoDate = (d: Date) => `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
const num = (v: unknown) => Number(v || 0) || 0;
const money = (v: unknown) => num(v).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
const nameOf = (session: Session | null, data?: BootstrapData | null) => data?.directory?.full_name || String(session?.user?.user_metadata?.full_name || session?.user?.user_metadata?.name || session?.user?.email?.split('@')[0] || 'Usuário');
const roleOf = (data?: BootstrapData | null) => data?.directory?.role_name || data?.directory?.job_title || 'Usuário';
const initials = (name: string) => name.split(' ').filter(Boolean).slice(0,2).map(x => x[0]?.toUpperCase()).join('') || 'MV';
const customerName = (c?: CustomerRow | null) => c?.trade_name || c?.legal_name || 'Loja';
const cacheKey = (userId: string) => `movvant.rc11.bootstrap.${userId}`;

async function saveBootstrap(userId: string, data: BootstrapData) {
  await AsyncStorage.setItem(cacheKey(userId), JSON.stringify(data));
}
async function readBootstrap(userId: string): Promise<BootstrapData | null> {
  const raw = await AsyncStorage.getItem(cacheKey(userId));
  if (!raw) return null;
  try { return JSON.parse(raw) as BootstrapData; } catch { return null; }
}

async function scheduleTripEndReminder(date:string,title:string){try{const permission=await Notifications.requestPermissionsAsync();if(permission.status!=='granted')return;if(Platform.OS==='android')await Notifications.setNotificationChannelAsync('trip-reminders',{name:'Viagens',importance:Notifications.AndroidImportance.DEFAULT});const when=new Date(`${date}T20:00:00`);if(when.getTime()<=Date.now())return;await Notifications.scheduleNotificationAsync({content:{title:'Finalizar viagem do dia',body:`Revise e finalize: ${title}`,sound:true},trigger:when as any});}catch{}}

async function savePrefs(p: Preferences) { await AsyncStorage.setItem(PREFS_KEY, JSON.stringify(p)); }
async function readPrefs(): Promise<Preferences> {
  const raw = await AsyncStorage.getItem(PREFS_KEY);
  if (!raw) return DEFAULT_PREFS;
  try { return { ...DEFAULT_PREFS, ...(JSON.parse(raw) as Partial<Preferences>) }; } catch { return DEFAULT_PREFS; }
}

function Field({ label, value, setValue, placeholder, secure = false, numeric = false, editable = true }: { label: string; value: string; setValue: (v: string) => void; placeholder?: string; secure?: boolean; numeric?: boolean; editable?: boolean }) {
  return <View style={s.field}><Text style={s.label}>{label}</Text><TextInput style={[s.input, !editable && s.inputOff]} value={value} onChangeText={setValue} placeholder={placeholder} secureTextEntry={secure} keyboardType={numeric ? 'numeric' : 'default'} editable={editable} autoCapitalize={label.toLowerCase().includes('e-mail') ? 'none' : 'sentences'} /></View>;
}
function Empty({ title, text }: { title: string; text: string }) { return <View style={s.empty}><Text style={s.emptyTitle}>{title}</Text><Text style={s.sub}>{text}</Text></View>; }
function Hero({ title, text }: { title: string; text: string }) { return <View style={s.hero}><Text style={s.heroTop}>MOVVANT ENTERPRISE</Text><Text style={s.heroTitle}>{title}</Text><Text style={s.heroText}>{text}</Text></View>; }
function Row({ icon, title, sub, onPress }: { icon: string; title: string; sub: string; onPress: () => void }) { return <Pressable style={s.row} onPress={onPress}><View style={s.rowIcon}><Text style={s.rowIconText}>{icon}</Text></View><View style={{ flex: 1 }}><Text style={s.rowTitle}>{title}</Text><Text style={s.sub}>{sub}</Text></View><Text style={s.rowArrow}>›</Text></Pressable>; }
function Header({ title, onMenu, onBack, unread, onNotifications }: { title: string; onMenu: () => void; onBack?: () => void; unread: number; onNotifications?:()=>void }) { return <View style={s.header}><Pressable style={s.headerBtn} onPress={onBack || onMenu}><Text style={s.headerBtnText}>{onBack ? '‹' : '☰'}</Text></Pressable><Text style={s.headerTitle}>{title}</Text><Pressable style={s.headerRight} onPress={onNotifications}>{unread > 0 && <View style={s.unreadBadge}><Text style={s.unreadText}>{unread > 99 ? '99+' : unread}</Text></View>}<Text style={s.headerBell}>●</Text></Pressable></View>; }
function Bottom({ tab, setTab }: { tab: Tab; setTab: (t: Tab) => void }) { const rows: Array<[Tab,string,string]> = [['home','⌂','Home'],['agenda','▣','Agenda'],['km','◎','KM'],['mapa','⌖','Mapa'],['mais','☰','Menu']]; return <View style={s.bottom}>{rows.map(([k,i,l]) => <Pressable key={k} style={s.bottomItem} onPress={() => setTab(k)}><Text style={[s.bottomIcon, tab === k && s.active]}>{i}</Text><Text style={[s.bottomLabel, tab === k && s.active]}>{l}</Text></Pressable>)}</View>; }
function Metric({ icon, value, label, tone }: { icon: string; value: string; label: string; tone: 'g'|'b'|'o' }) { const bg = tone === 'g' ? '#E7F7F0' : tone === 'b' ? '#EAF2FE' : '#FFF3E5'; const color = tone === 'g' ? GREEN : tone === 'b' ? BLUE : ORANGE; return <View style={s.metric}><View style={[s.metricIcon,{ backgroundColor: bg }]}><Text style={{ color, fontWeight: '900' }}>{icon}</Text></View><Text style={s.metricValue}>{value}</Text><Text style={s.metricLabel}>{label}</Text></View>; }

function Login({ onLogin }: { onLogin: (session: Session) => void }) {
  const [email,setEmail] = useState(''); const [password,setPassword] = useState(''); const [loading,setLoading] = useState(false);
  const submit = async () => {
    if (!email.trim() || !password) return Alert.alert('Acesso', 'Informe e-mail e senha.');
    setLoading(true);
    try {
      const session = await signIn(email, password);
      await AsyncStorage.setItem(SESSION_KEY, JSON.stringify(session));
      onLogin(session);
    } catch (e) { Alert.alert('Não foi possível entrar', e instanceof Error ? e.message : 'Verifique e-mail, senha e conexão.'); }
    finally { setLoading(false); }
  };
  return <SafeAreaView style={s.login}><StatusBar barStyle="light-content" backgroundColor={NAVY}/><View style={s.loginHero}><View style={s.logo}><Text style={s.logoText}>M</Text></View><Text style={s.brand}>Movvant</Text><Text style={s.enterprise}>ENTERPRISE</Text><Text style={s.tag}>A gestão em movimento</Text></View><View style={s.loginCard}><Text style={s.loginTitle}>Bem-vindo</Text><Text style={s.loginSub}>Entre para acessar sua operação</Text><Field label="E-mail" value={email} setValue={setEmail} placeholder="seu@email.com"/><Field label="Senha" value={password} setValue={setPassword} secure placeholder="••••••••"/><Pressable style={[s.primary, loading && s.disabled]} onPress={submit} disabled={loading}><Text style={s.primaryText}>{loading ? 'Entrando...' : 'Entrar'}</Text></Pressable><Text style={s.loginFoot}>Mobilidade que impulsiona resultados</Text><Text style={s.version}>Movvant Mobile · Integrado</Text></View></SafeAreaView>;
}

function AgendaRow({ item, onPress }: { item: Appointment; onPress?: () => void }) { return <Pressable style={s.agendaRow} onPress={onPress}><Text style={s.time}>{item.time}</Text><View style={[s.greenLine, item.local && { backgroundColor: ORANGE }]}/><View style={{ flex: 1 }}><Text style={s.store}>{item.store}</Text><Text style={s.sub}>{item.title}{item.local ? ' · aguardando sincronização' : ''}</Text></View><Text style={s.rowArrow}>›</Text></Pressable>; }

function Home({ session, data, local, appointments, online, pending, goAgenda, goMap }: { session: Session; data: BootstrapData | null; local: LocalState; appointments: Appointment[]; online: boolean; pending: number; goAgenda: () => void; goMap: () => void }) {
  const today = new Date(); const todayKey = isoDate(today); const name = nameOf(session,data);
  const todayItems = appointments.filter(x => x.date === todayKey).sort((a,b) => a.time.localeCompare(b.time));
  const todayStores = new Set(todayItems.map(x => x.customerId).filter(Boolean)).size;
  const localKm = local.km.filter(x => x.createdAt.slice(0,10) === todayKey).reduce((n,x) => n + x.total, 0);
  const localTripKm = local.trips.filter(x => isoDate(new Date(x.finishedAt)) === todayKey).reduce((n,x) => n + x.distanceMeters / 1000, 0);
  const km = localKm || localTripKm;
  return <ScrollView contentContainerStyle={s.content} keyboardShouldPersistTaps="handled" automaticallyAdjustKeyboardInsets>
    <View style={s.profile}><View style={s.avatar}><Text style={s.avatarText}>{initials(name)}</Text></View><View style={{ flex: 1 }}><Text style={s.hello}>Olá, {name.split(' ')[0]}</Text><Text style={s.muted}>{roleOf(data)}{data?.directory?.branch_name ? ` · ${data.directory.branch_name}` : ''}</Text><Text style={s.dateText}>{WEEK[today.getDay()]}, {today.getDate()} de {MONTHS[today.getMonth()].toLowerCase()}</Text></View></View>
    <View style={s.metricRow}><Metric icon="▦" value={String(todayStores)} label="Lojas hoje" tone="g"/><Metric icon="◷" value={String(todayItems.length)} label="Compromissos" tone="b"/><Metric icon="⌖" value={`${km.toFixed(1)} km`} label="Percorridos" tone="o"/></View>
    <View style={s.sectionHead}><Text style={s.sectionTitle}>Próximos compromissos</Text><Pressable onPress={goAgenda}><Text style={s.link}>Ver todos</Text></Pressable></View>
    {todayItems.length ? todayItems.slice(0,4).map(x => <AgendaRow key={x.id} item={x}/>) : <Empty title="Agenda livre hoje" text="Seus próximos compromissos aparecerão aqui."/>}
    <Pressable style={s.primary} onPress={goMap}><Text style={s.primaryText}>Iniciar deslocamento</Text></Pressable>
    <View style={s.syncCard}><View style={[s.syncCheck, !online && { backgroundColor: '#FFF3E5' }]}><Text style={[s.syncCheckText, !online && { color: ORANGE }]}>{online ? '✓' : '!'}</Text></View><View style={{ flex: 1 }}><Text style={s.syncTitle}>{online ? 'Conectado ao Movvant' : 'Trabalhando offline'}</Text><Text style={s.sub}>{pending ? `${pending} registro(s) aguardando envio.` : 'Fila local sem pendências.'}</Text></View><View style={[s.onlineDot, !online && { backgroundColor: ORANGE }]}/></View>
    {!data?.companyId && <Empty title="Sem vínculo empresarial" text="Seu login é válido, mas não há empresa ativa vinculada ao perfil. Solicite a liberação do administrador."/>}
  </ScrollView>;
}

function CustomerPicker({ visible, customers, selected, close, select }: { visible: boolean; customers: CustomerRow[]; selected?: string; close: () => void; select: (c: CustomerRow) => void }) {
  const [q,setQ] = useState('');
  useEffect(() => { if (!visible) setQ(''); }, [visible]);
  const rows = customers.filter(c => `${customerName(c)} ${c.legal_name} ${c.city || ''} ${c.state || ''}`.toLowerCase().includes(q.trim().toLowerCase())).slice(0,100);
  return <Modal visible={visible} animationType="slide" onRequestClose={close}><SafeAreaView style={s.screen}><View style={s.modalHeader}><Pressable onPress={close}><Text style={s.modalBack}>‹</Text></Pressable><Text style={s.modalTitle}>Selecionar loja</Text><View style={{ width: 32 }}/></View><View style={s.modalSearch}><TextInput value={q} onChangeText={setQ} placeholder="Buscar loja, cidade..." style={s.searchInput}/></View><ScrollView contentContainerStyle={s.modalList} keyboardShouldPersistTaps="handled" automaticallyAdjustKeyboardInsets>{rows.map(c => <Pressable key={c.id} style={[s.selectRow, selected === c.id && s.selectRowOn]} onPress={() => { select(c); close(); }}><View><Text style={s.rowTitle}>{customerName(c)}</Text><Text style={s.sub}>{[c.city,c.state].filter(Boolean).join(' · ') || c.legal_name}</Text></View>{selected === c.id && <Text style={s.check}>✓</Text>}</Pressable>)}{!rows.length && <Empty title="Nenhuma loja encontrada" text="A busca respeita a carteira disponível para seu usuário."/>}</ScrollView></SafeAreaView></Modal>;
}

function VehiclePicker({ visible, vehicles, selected, close, select }: { visible: boolean; vehicles: VehicleRow[]; selected?: string; close: () => void; select: (v: VehicleRow) => void }) {
  return <Modal visible={visible} animationType="slide" onRequestClose={close}><SafeAreaView style={s.screen}><View style={s.modalHeader}><Pressable onPress={close}><Text style={s.modalBack}>‹</Text></Pressable><Text style={s.modalTitle}>Selecionar veículo</Text><View style={{ width: 32 }}/></View><ScrollView contentContainerStyle={s.modalList} keyboardShouldPersistTaps="handled" automaticallyAdjustKeyboardInsets>{vehicles.map(v => <Pressable key={v.id} style={[s.selectRow, selected === v.id && s.selectRowOn]} onPress={() => { select(v); close(); }}><View><Text style={s.rowTitle}>{v.plate}</Text><Text style={s.sub}>{[v.make,v.model].filter(Boolean).join(' ') || 'Veículo'}</Text></View>{selected === v.id && <Text style={s.check}>✓</Text>}</Pressable>)}{!vehicles.length && <Empty title="Nenhum veículo disponível" text="Seu perfil não possui veículo ativo atribuído."/>}</ScrollView></SafeAreaView></Modal>;
}

function Agenda({ appointments, customers, userId, onSave, onSaveTravel, onDelete }: { appointments: Appointment[]; customers: CustomerRow[]; userId?:string; onSave: (item: LocalAppointment) => Promise<void>; onSaveTravel: (item: LocalAppointment) => Promise<void>; onDelete: (id: string) => Promise<void> }) {
  const now=new Date();
  const [cursor,setCursor]=useState(new Date(now.getFullYear(),now.getMonth(),1));
  const [selected,setSelected]=useState(isoDate(now));
  const [open,setOpen]=useState(false);
  const [editing,setEditing]=useState<Appointment|null>(null);
  const [title,setTitle]=useState('');
  const [time,setTime]=useState('09:00');
  const [customer,setCustomer]=useState<CustomerRow|null>(null);
  const [picker,setPicker]=useState(false);
  const [tripPlanner,setTripPlanner]=useState(false);
  const [editingTrip,setEditingTrip]=useState<Appointment|null>(null);
  const y=cursor.getFullYear(),m=cursor.getMonth(),first=new Date(y,m,1).getDay(),days=new Date(y,m+1,0).getDate();
  const cells=Array.from({length:first+days},(_,i)=>i<first?null:i-first+1);
  const monthPrefix=`${y}-${pad(m+1)}`;
  const monthItems=useMemo(()=>appointments.filter(x=>x.date.startsWith(monthPrefix)).sort((a,b)=>`${a.date} ${a.time}`.localeCompare(`${b.date} ${b.time}`)),[appointments,monthPrefix]);
  const dayItems=useMemo(()=>appointments.filter(x=>x.date===selected).sort((a,b)=>a.time.localeCompare(b.time)),[appointments,selected]);
  const selectedObj=new Date(`${selected}T12:00:00`);
  const change=(d:number)=>{const n=new Date(y,m+d,1);setCursor(n);setSelected(isoDate(n.getFullYear()===now.getFullYear()&&n.getMonth()===now.getMonth()?now:n));};
  const newItem=()=>{setEditing(null);setTitle('');setTime('09:00');setCustomer(null);setOpen(true);};
  const openItem=(item:Appointment)=>{if(item.type==='Viagem'&&item.travel){setEditingTrip(item);setTripPlanner(true);return}setEditing(item);setTitle(item.title);setTime(item.time);setCustomer(customers.find(c=>c.id===item.customerId)||null);setOpen(true);};
  const save=async()=>{
    if(editing && !editing.local) return setOpen(false);
    if(!title.trim()) return Alert.alert('Compromisso','Informe um título.');
    if(!/^([01]\d|2[0-3]):[0-5]\d$/.test(time)) return Alert.alert('Horário','Use o formato HH:MM.');
    const item:LocalAppointment={id:editing?.id||`${Date.now()}-appointment`,date:selected,time,title:title.trim(),store:customer?customerName(customer):editing?.store||'Sem loja definida',type:'Compromisso',customerId:customer?.id||editing?.customerId,synced:false};
    await onSave(item);setOpen(false);setEditing(null);
  };
  const remove=()=>{if(!editing?.local)return;Alert.alert('Excluir compromisso','Deseja remover este compromisso do aparelho?',[{text:'Cancelar',style:'cancel'},{text:'Excluir',style:'destructive',onPress:async()=>{await onDelete(editing.id);setOpen(false);setEditing(null);}}]);};
  const saveTrip=async(trip:PlannedTrip)=>{const item:LocalAppointment={id:editingTrip?.id||`${Date.now()}-travel`,date:trip.date,time:trip.time,title:`Viagem · ${trip.origin} → ${trip.destination}`,store:trip.destination,type:'Viagem',synced:false,routeStatus:editingTrip?.routeStatus||'planned',routeStatusAt:editingTrip?.routeStatusAt,travel:{origin:trip.origin,destination:trip.destination,stops:trip.stops,roundTrip:trip.roundTrip,optimizeStops:trip.optimizeStops,distanceMeters:trip.distanceMeters,durationSeconds:trip.durationSeconds,tollBRL:trip.tollBRL,routeLabel:trip.routeLabel,polyline:trip.polyline,returnPolyline:trip.returnPolyline,plannedExpenses:trip.plannedExpenses}};await onSaveTravel(item);await scheduleTripEndReminder(trip.date,item.title);setSelected(trip.date);setCursor(new Date(`${trip.date}T12:00:00`));setEditingTrip(null);};
  const setRouteStatus=async(item:Appointment,status:'completed'|'cancelled')=>{const local=item as LocalAppointment;await onSaveTravel({...local,routeStatus:status,routeStatusAt:new Date().toISOString(),synced:false});};
  return <ScrollView contentContainerStyle={s.content} keyboardShouldPersistTaps="handled" automaticallyAdjustKeyboardInsets>
    <View style={s.agendaHero}><Text style={s.agendaEyebrow}>AGENDA COMERCIAL</Text><Text style={s.agendaHeroTitle}>Compromissos e visitas</Text><Text style={s.agendaHeroText}>Planeje o mês, acompanhe o dia e visualize o estado de cada compromisso.</Text></View>
    <View style={s.agendaSummary}><View style={s.agendaSummaryItem}><Text style={s.agendaSummaryValue}>{monthItems.length}</Text><Text style={s.agendaSummaryLabel}>No mês</Text></View><View style={s.agendaSummaryItem}><Text style={s.agendaSummaryValue}>{dayItems.length}</Text><Text style={s.agendaSummaryLabel}>No dia</Text></View><View style={s.agendaSummaryItem}><Text style={s.agendaSummaryValue}>{monthItems.filter(x=>x.local).length}</Text><Text style={s.agendaSummaryLabel}>Pendentes</Text></View></View>
    <View style={s.calendar}><View style={s.monthHead}><Pressable style={s.monthNav} onPress={()=>change(-1)}><Text style={s.arrow}>‹</Text></Pressable><View><Text style={s.monthTitle}>{MONTHS[m]} {y}</Text><Text style={s.monthSub}>{monthItems.length} compromisso(s) no mês</Text></View><Pressable style={s.monthNav} onPress={()=>change(1)}><Text style={s.arrow}>›</Text></Pressable></View><View style={s.week}>{['D','S','T','Q','Q','S','S'].map((x,i)=><Text key={i} style={s.weekText}>{x}</Text>)}</View><View style={s.days}>{cells.map((d,i)=>!d?<View key={`e-${i}`} style={s.dayCell}/>:<Pressable key={d} style={s.dayCell} onPress={()=>setSelected(isoDate(new Date(y,m,d)))}><View style={[s.dayCircle,selected===isoDate(new Date(y,m,d))&&s.daySelected]}><Text style={[s.dayText,selected===isoDate(new Date(y,m,d))&&s.dayTextSelected]}>{d}</Text></View>{appointments.some(x=>x.date===isoDate(new Date(y,m,d)))&&<View style={s.dayDot}/>}</Pressable>)}</View></View>
    <View style={s.sectionHead}><View><Text style={s.sectionTitle}>{WEEK[selectedObj.getDay()]}, {selectedObj.getDate()} de {MONTHS[selectedObj.getMonth()].toLowerCase()}</Text><Text style={s.sub}>{dayItems.length?`${dayItems.length} compromisso(s)`:'Agenda livre'}</Text></View><View style={{flexDirection:'row',gap:8}}><Pressable style={s.tripAgendaButton} onPress={()=>{setEditingTrip(null);setTripPlanner(true)}}><Text style={s.tripAgendaButtonText}>+ Viagem</Text></Pressable><Pressable style={s.newAgendaButton} onPress={newItem}><Text style={s.newAgendaButtonText}>+ Novo</Text></Pressable></View></View>
    {dayItems.length?dayItems.map(x=><Pressable key={x.id} style={s.agendaDetailCard} onPress={()=>openItem(x)}><View style={s.agendaDateBadge}><Text style={s.agendaDateDay}>{Number(x.date.slice(8,10))}</Text><Text style={s.agendaDateMonth}>{MONTHS[Number(x.date.slice(5,7))-1].slice(0,3).toUpperCase()}</Text></View><View style={{flex:1}}><Text style={s.store}>{x.store}</Text><Text style={s.agendaTitleLine}>{x.title}</Text><Text style={s.sub}>{x.time}{x.travel?` · ${(x.travel.distanceMeters/1000).toFixed(1)} km · pedágios ${money(x.travel.tollBRL)}`:''}</Text><View style={s.agendaBadges}><View style={[s.agendaState,x.routeStatus==='cancelled'?{backgroundColor:'#FCE8E8'}:x.routeStatus==='completed'?s.agendaStateOk:x.local?s.agendaStatePending:s.agendaStateOk]}><Text style={[s.agendaStateText,x.routeStatus==='cancelled'?{color:RED}:x.routeStatus==='completed'?s.agendaStateTextOk:x.local?s.agendaStateTextPending:s.agendaStateTextOk]}>{x.routeStatus==='cancelled'?'Rota cancelada':x.routeStatus==='completed'?'Rota finalizada':x.local?'Aguardando sincronização':/complete|done|realiz|finish/i.test(x.status||'')?'Realizada':'Sincronizada'}</Text></View>{x.customerId&&<View style={s.agendaSource}><Text style={s.agendaSourceText}>Loja vinculada</Text></View>}</View>{x.type==='Viagem'&&x.routeStatus!=='completed'&&x.routeStatus!=='cancelled'&&<View style={{flexDirection:'row',gap:8,marginTop:8}}><Pressable style={s.tripAgendaButton} onPress={(e)=>{e.stopPropagation();setRouteStatus(x,'completed')}}><Text style={s.tripAgendaButtonText}>Finalizar rota</Text></Pressable><Pressable style={s.newAgendaButton} onPress={(e)=>{e.stopPropagation();setRouteStatus(x,'cancelled')}}><Text style={s.newAgendaButtonText}>Cancelar rota</Text></Pressable></View>}</View><Text style={s.rowArrow}>›</Text></Pressable>):<Empty title="Nenhum compromisso" text="Toque em + Novo para adicionar uma visita, reunião ou compromisso."/>}
    {monthItems.length>0&&<View style={s.monthList}><Text style={s.sectionTitle}>Compromissos do mês</Text>{monthItems.slice(0,12).map(x=><Pressable key={`m-${x.id}`} style={s.monthListRow} onPress={()=>{setSelected(x.date);openItem(x)}}><View style={s.monthListDate}><Text style={s.monthListDay}>{Number(x.date.slice(8,10))}</Text><Text style={s.monthListMon}>{MONTHS[Number(x.date.slice(5,7))-1].slice(0,3).toUpperCase()}</Text></View><View style={{flex:1}}><Text style={s.rowTitle} numberOfLines={1}>{x.title}</Text><Text style={s.sub} numberOfLines={1}>{x.time} · {x.store}</Text></View><Text style={[s.monthListStatus,x.local&&{color:ORANGE}]}>{x.local?'Local':'✓'}</Text></Pressable>)}</View>}
    <TripPlannerScreen visible={tripPlanner} customers={customers} initialDate={selected} initialTrip={editingTrip?.travel?{date:editingTrip.date,time:editingTrip.time,...editingTrip.travel}:null} userId={userId} onClose={()=>{setTripPlanner(false);setEditingTrip(null)}} onSave={saveTrip}/>
    <Modal visible={open} animationType="slide" onRequestClose={()=>setOpen(false)}><SafeAreaView style={s.screen}><View style={s.modalHeader}><Pressable onPress={()=>setOpen(false)}><Text style={s.modalBack}>‹</Text></Pressable><Text style={s.modalTitle}>{editing?'Compromisso':'Novo compromisso'}</Text><View style={{width:32}}/></View><ScrollView contentContainerStyle={s.content} keyboardShouldPersistTaps="handled" automaticallyAdjustKeyboardInsets><Field label="Título" value={title} setValue={setTitle} editable={!editing||Boolean(editing.local)} placeholder="Ex.: Visita comercial"/><Field label="Data" value={`${pad(selectedObj.getDate())}/${pad(selectedObj.getMonth()+1)}/${selectedObj.getFullYear()}`} setValue={()=>{}} editable={false}/><Field label="Horário" value={time} setValue={setTime} editable={!editing||Boolean(editing.local)}/><View style={s.field}><Text style={s.label}>Loja</Text><Pressable style={s.inputButton} onPress={()=>!editing||editing.local?setPicker(true):undefined}><Text style={customer?s.inputButtonText:s.inputPlaceholder}>{customer?customerName(customer):editing?.store||'Selecionar loja'}</Text><Text style={s.rowArrow}>›</Text></Pressable></View>{editing&&!editing.local?<Empty title="Compromisso sincronizado" text={`Status: ${editing.status||'planejado'}. Alterações remotas respeitam a permissão empresarial.`}/>:<Pressable style={s.primary} onPress={save}><Text style={s.primaryText}>{editing?'Salvar alterações':'Salvar compromisso'}</Text></Pressable>}{editing?.local&&<Pressable style={s.logout} onPress={remove}><Text style={s.logoutText}>Excluir compromisso</Text></Pressable>}</ScrollView><CustomerPicker visible={picker} customers={customers} selected={customer?.id} close={()=>setPicker(false)} select={setCustomer}/></SafeAreaView></Modal>
  </ScrollView>;
}

function Km({ vehicles, history, onSave, companyId }: { vehicles: VehicleRow[]; history: LocalKmRecord[]; onSave: (item: LocalKmRecord) => Promise<void>; companyId?: string | null }) {
  const [tab,setTab] = useState<'register'|'history'>('register'); const [vehicle,setVehicle] = useState<VehicleRow | null>(vehicles[0] || null); const [start,setStart] = useState(''); const [end,setEnd] = useState(''); const [reason,setReason] = useState(''); const [photo,setPhoto] = useState<string | null>(null); const [picker,setPicker] = useState(false); const [kmSettings,setKmSettings] = useState<EnterpriseSettings['km']>(DEFAULT_ENTERPRISE_SETTINGS.km);
  useEffect(() => { if (!vehicle && vehicles[0]) setVehicle(vehicles[0]); }, [vehicles,vehicle]);
  useEffect(() => { readEnterpriseSettings(companyId).then(x => setKmSettings(x.km)).catch(() => setKmSettings(DEFAULT_ENTERPRISE_SETTINGS.km)); }, [companyId]);
  const a = Number(start.replace(/\D/g,'')), b = Number(end.replace(/\D/g,'')); const total = start && end && b >= a ? b - a : 0;
  const capture = async () => {
    const permission = await ImagePicker.requestCameraPermissionsAsync();
    if (!permission.granted) return Alert.alert('Câmera', 'Permita o uso da câmera para anexar a foto.');
    const result = await ImagePicker.launchCameraAsync({ mediaTypes: ['images'], quality: 0.7, allowsEditing: false });
    if (!result.canceled && result.assets[0]?.uri) setPhoto(result.assets[0].uri);
  };
  const save = async () => {
    if (!kmSettings.allowManualKm) return Alert.alert('Registro de KM', 'O lançamento manual está desativado nas regras desta empresa.');
    if (kmSettings.requireVehicle && !vehicle) return Alert.alert('Veículo', 'Selecione um veículo.');
    if (!vehicle) return Alert.alert('Veículo', 'O registro sem veículo ainda não pode ser sincronizado.');
    if (kmSettings.requirePhoto && !photo) return Alert.alert('Foto obrigatória', 'Anexe a foto do painel antes de salvar o registro.');
    if (!start || !end) return Alert.alert('Registro de KM', 'Informe KM inicial e KM final.');
    if (b < a) return Alert.alert('KM inválido', 'O KM final não pode ser menor que o inicial.');
    const item: LocalKmRecord = { id: `${Date.now()}-km`, vehicleId: vehicle.id, vehicle: vehicle.plate, start: a, end: b, total, reason: reason.trim(), photoUri: photo, createdAt: new Date().toISOString(), synced: false };
    await onSave(item); setStart(''); setEnd(''); setReason(''); setPhoto(null); Alert.alert('Registro salvo', 'O KM foi salvo localmente e entrou na fila de sincronização.');
  };
  return <ScrollView contentContainerStyle={s.content} keyboardShouldPersistTaps="handled" automaticallyAdjustKeyboardInsets><View style={s.segment}><Pressable style={[s.segmentTab,tab==='register'&&s.segmentOn]} onPress={() => setTab('register')}><Text style={[s.segmentText,tab==='register'&&s.segmentTextOn]}>Registrar</Text></Pressable><Pressable style={[s.segmentTab,tab==='history'&&s.segmentOn]} onPress={() => setTab('history')}><Text style={[s.segmentText,tab==='history'&&s.segmentTextOn]}>Histórico</Text></Pressable></View>
    {tab === 'register' ? <>{!kmSettings.allowManualKm&&<Empty title="Lançamento manual desativado" text="As regras da empresa bloqueiam registros manuais de KM neste aparelho."/>}<View style={s.field}><Text style={s.label}>Veículo</Text><Pressable style={s.inputButton} onPress={() => setPicker(true)}><Text style={vehicle ? s.inputButtonText : s.inputPlaceholder}>{vehicle ? `${vehicle.plate}${vehicle.model ? ` · ${vehicle.model}` : ''}` : 'Selecionar veículo'}</Text><Text style={s.rowArrow}>›</Text></Pressable></View><Field label="KM inicial" value={start} setValue={setStart} numeric placeholder={vehicle?.current_odometer_km ? String(Math.round(num(vehicle.current_odometer_km))) : '0'}/><Field label="KM final" value={end} setValue={setEnd} numeric placeholder="0"/><View style={s.total}><View><Text style={s.muted}>Distância percorrida</Text><Text style={s.totalHint}>Cálculo automático</Text></View><Text style={s.totalValue}>{total} km</Text></View><Field label="Motivo" value={reason} setValue={setReason} placeholder="Ex.: Visita a lojas"/><Pressable style={[s.attach,photo&&s.attachDone]} onPress={capture}><Text style={s.attachIcon}>{photo ? '✓' : '▧'}</Text><View><Text style={s.rowTitle}>{photo ? 'Foto anexada' : 'Adicionar foto'}</Text><Text style={s.sub}>{photo ? 'Toque para substituir' : kmSettings.requirePhoto ? 'Obrigatória pelas regras da empresa' : 'Opcional · comprovante ou painel'}</Text></View></Pressable>{photo ? <View style={s.photoPreviewCard}><Image source={{uri:photo}} style={s.photoPreview}/><View style={{flex:1}}><Text style={s.rowTitle}>Comprovante pronto</Text><Text style={s.sub}>A imagem será enviada com o registro quando houver sincronização.</Text></View></View> : null}<Pressable style={s.primary} onPress={save}><Text style={s.primaryText}>Salvar registro</Text></Pressable><VehiclePicker visible={picker} vehicles={vehicles} selected={vehicle?.id} close={() => setPicker(false)} select={setVehicle}/></> : history.length ? history.map(x => <View style={s.historyCard} key={x.id}><View style={s.historyHead}><Text style={s.rowTitle}>{x.vehicle}</Text><Text style={[s.statusPill,x.synced&&s.statusPillOk]}>{x.synced?'Enviado':'Local'}</Text></View><Text style={s.historyKm}>{x.total} km</Text><Text style={s.sub}>{new Date(x.createdAt).toLocaleString('pt-BR')} · {x.start} → {x.end}</Text>{x.reason ? <Text style={s.sub}>{x.reason}</Text> : null}{x.photoUri ? <Text style={s.photoState}>✓ Foto anexada</Text> : <Text style={s.photoStateMuted}>Sem foto</Text>}</View>) : <Empty title="Histórico vazio" text="Os registros feitos neste aparelho aparecerão aqui."/>}
  </ScrollView>;
}

function Stores({ customers, branchId, branchScoped }: { customers: CustomerRow[]; branchId: string | null; branchScoped: boolean }) {
  const [q,setQ] = useState('');
  const scoped = branchScoped && branchId ? customers.filter(c => !c.branch_id || c.branch_id === branchId) : customers;
  const rows = scoped.filter(c => `${customerName(c)} ${c.legal_name} ${c.city || ''} ${c.state || ''}`.toLowerCase().includes(q.toLowerCase()));
  return <ScrollView contentContainerStyle={s.content} keyboardShouldPersistTaps="handled" automaticallyAdjustKeyboardInsets><View style={s.search}><Text style={s.searchIcon}>⌕</Text><TextInput style={s.searchTextInput} value={q} onChangeText={setQ} placeholder="Buscar loja..."/></View><View style={s.listCount}><Text style={s.sectionTitle}>Carteira</Text><Text style={s.muted}>{rows.length} loja(s)</Text></View>{rows.length ? rows.map(c => <View style={s.storeCard} key={c.id}><View style={s.storeBadge}><Text style={s.storeBadgeText}>▦</Text></View><View style={{flex:1}}><Text style={s.rowTitle}>{customerName(c)}</Text><Text style={s.sub}>{[c.city,c.state].filter(Boolean).join(' · ') || c.legal_name}</Text></View></View>) : <Empty title="Nenhuma loja encontrada" text="A carteira exibida respeita os dados disponíveis para seu usuário."/>}</ScrollView>;
}

function Reports({ data, local }: { data: BootstrapData | null; local: LocalState }) {
  const perf=data?.performance;
  const [period,setPeriod]=useState<'day'|'week'|'month'|'custom'>('month');
  const [activityCategory,setActivityCategory]=useState<'all'|'commercial'|'delivery'|'travel'>('all');
  const [customFrom,setCustomFrom]=useState(isoDate(new Date())),[customTo,setCustomTo]=useState(isoDate(new Date())),[expenseRows,setExpenseRows]=useState<any[]>([]);
  useEffect(()=>{readExpenses(data?.companyId||'local').then(setExpenseRows).catch(()=>setExpenseRows([]))},[data?.companyId]);
  const start=useMemo(()=>{if(period==='custom'){const t=new Date(`${customFrom}T00:00:00`).getTime();return Number.isFinite(t)?t:Date.now()}const d=new Date();d.setHours(0,0,0,0);if(period==='week')d.setDate(d.getDate()-6);if(period==='month')d.setDate(1);return d.getTime()},[period,customFrom]);
  const end=period==='custom'?new Date(`${customTo}T23:59:59`).getTime():Date.now();
  const localKmRecords=local.km.filter(x=>{const t=new Date(x.createdAt).getTime();return t>=start&&t<=end});
  const inPeriodAppointments=local.appointments.filter(x=>new Date(`${x.date}T12:00:00`).getTime()>=start&&new Date(`${x.date}T12:00:00`).getTime()<=end);const kind=(x:any)=>/entrega|delivery|log[ií]st/i.test(`${x.type} ${x.title}`)?'delivery':/viagem|rota/i.test(`${x.type} ${x.title}`)?'travel':'commercial';const filteredAppointments=activityCategory==='all'?inPeriodAppointments:inPeriodAppointments.filter(x=>kind(x)===activityCategory);const filteredIds=new Set(filteredAppointments.map(x=>x.id));const localTrips=local.trips.filter(x=>x.finishedAt>=start&&x.finishedAt<=end&&(activityCategory==='all'||(x.plannedTripId&&filteredIds.has(x.plannedTripId))));const routeAppointments=filteredAppointments.filter(x=>x.type==='Viagem');const plannedRoutes=routeAppointments.filter(x=>(x.routeStatus||'planned')==='planned').length,completedRoutes=routeAppointments.filter(x=>x.routeStatus==='completed').length,cancelledRoutes=routeAppointments.filter(x=>x.routeStatus==='cancelled').length;
  const localVisits=local.visits.filter(x=>{const t=new Date(x.updatedAt).getTime();return t>=start&&t<=end});
  const localKm=localKmRecords.reduce((n,x)=>n+x.total,0),tripKm=localTrips.reduce((n,x)=>n+x.distanceMeters/1000,0),tripMinutes=localTrips.reduce((n,x)=>n+x.elapsedMs/60000,0);
  const comparedTrips=localTrips.filter(x=>(x.plannedDistanceMeters||0)>0),plannedKm=comparedTrips.reduce((n,x)=>n+(x.plannedDistanceMeters||0)/1000,0),actualComparedKm=comparedTrips.reduce((n,x)=>n+x.distanceMeters/1000,0),extraStops=localTrips.reduce((n,x)=>n+(x.deviations?.filter(d=>d.classification!=='dismissed').length||0),0),confirmedExtraVisits=localTrips.reduce((n,x)=>n+(x.deviations?.filter(d=>d.classification==='confirmed_visit').length||0),0),routeOccurrences=localTrips.reduce((n,x)=>n+(x.deviations?.filter(d=>d.classification==='occurrence'||d.classification==='detected'||!d.classification).length||0),0),distanceVarianceKm=actualComparedKm-plannedKm;
  const expenseVisible=expenseRows.filter(x=>{const t=new Date(`${x.date}T12:00:00`).getTime();if(!(t>=start&&t<=end))return false;if(activityCategory==='all')return true;if(x.tripId)return filteredIds.has(x.tripId);return activityCategory==='commercial'&&x.category==='commercial'}),expenseSummary=summarizeExpenses(expenseVisible);const agendaPlanned=routeAppointments.reduce((n,x)=>n+Number(x.travel?.tollBRL||0)+(x.travel?.plannedExpenses||[]).reduce((a,e)=>a+Number(e.amount||0),0),0);
  const periodLabel=period==='day'?'Hoje':period==='week'?'Últimos 7 dias':period==='month'?'Este mês':`${customFrom} a ${customTo}`;
  const share=async()=>{const text=[`Movvant Enterprise — visão gerencial`,`Período local: ${periodLabel}`,`KM registrado: ${localKm.toFixed(1)} km`,`Deslocamentos: ${localTrips.length}`,`Tempo em deslocamento: ${Math.round(tripMinutes)} min`,`Visitas locais: ${localVisits.length}`,`Despesas previstas: ${money(expenseSummary.planned)}`,`Despesas realizadas: ${money(expenseSummary.actual)}`,`Potencial a reembolsar: ${money(expenseSummary.reimbursement)}`,`Visitas remotas 30d: ${num(perf?.visits_30d)}`,`Receita remota 30d: ${money(perf?.revenue_30d)}`].join('\n');await Share.share({message:text,title:'Visão gerencial Movvant'});};
  return <ScrollView contentContainerStyle={s.content} keyboardShouldPersistTaps="handled" automaticallyAdjustKeyboardInsets>
    <View style={s.managementHero}><Text style={s.agendaEyebrow}>VISÃO GERENCIAL</Text><Text style={s.managementTitle}>Resumo do período</Text><Text style={s.managementText}>Veja primeiro o que aconteceu no período e depois compare planejamento, execução e despesas.</Text></View>
    <View style={s.periodTabs}><Pressable style={[s.periodTab,period==='day'&&s.periodTabOn]} onPress={()=>setPeriod('day')}><Text style={[s.periodTabText,period==='day'&&s.periodTabTextOn]}>Dia</Text></Pressable><Pressable style={[s.periodTab,period==='week'&&s.periodTabOn]} onPress={()=>setPeriod('week')}><Text style={[s.periodTabText,period==='week'&&s.periodTabTextOn]}>Semana</Text></Pressable><Pressable style={[s.periodTab,period==='month'&&s.periodTabOn]} onPress={()=>setPeriod('month')}><Text style={[s.periodTabText,period==='month'&&s.periodTabTextOn]}>Mês</Text></Pressable><Pressable style={[s.periodTab,period==='custom'&&s.periodTabOn]} onPress={()=>setPeriod('custom')}><Text style={[s.periodTabText,period==='custom'&&s.periodTabTextOn]}>Período</Text></Pressable></View>{period==='custom'&&<View style={{flexDirection:'row',gap:8}}><DatePickerField label="De" value={customFrom} onChange={setCustomFrom}/><DatePickerField label="Até" value={customTo} onChange={setCustomTo}/></View>}
    <View style={s.categoryTabs}>{[['all','Todas'],['commercial','Visitas comerciais'],['delivery','Entregas'],['travel','Viagens']].map(([k,l])=><Pressable key={k} style={[s.categoryTab,activityCategory===k&&s.categoryTabOn]} onPress={()=>setActivityCategory(k as any)}><Text style={[s.categoryTabText,activityCategory===k&&s.categoryTabTextOn]}>{l}</Text></Pressable>)}</View><View style={s.periodCard}><Text style={s.periodLabel}>PERÍODO SELECIONADO</Text><Text style={s.periodValue}>{periodLabel}</Text><Text style={s.sub}>{new Date(start).toLocaleDateString('pt-BR')} → {new Date(end).toLocaleDateString('pt-BR')}</Text></View>
    <View style={s.reportWide}><Text style={s.reportWideTitle}>Situação das rotas</Text><Text style={s.reportWideSub}>Programadas {plannedRoutes} · Finalizadas {completedRoutes} · Canceladas {cancelledRoutes}</Text></View><View style={s.reportWide}><Text style={s.reportWideTitle}>O que aconteceu</Text><Text style={s.reportWideSub}>{localTrips.length} deslocamento(s) · {tripKm.toFixed(1)} km por GPS · {Math.round(tripMinutes)} min em rota · {localVisits.length} visita(s).</Text></View><View style={s.reportGrid}><View style={s.reportCard}><Text style={s.reportKicker}>KM LANÇADO</Text><Text style={s.reportValue}>{localKm.toFixed(1)} km</Text><Text style={s.metricLabel}>Odômetro/manual · {localKmRecords.length} lançamento(s)</Text></View><View style={s.reportCard}><Text style={s.reportKicker}>GPS / DESLOCAMENTOS</Text><Text style={s.reportValue}>{localTrips.length}</Text><Text style={s.metricLabel}>{tripKm.toFixed(1)} km rastreados por GPS</Text></View><View style={s.reportCard}><Text style={s.reportKicker}>TEMPO EM ROTA</Text><Text style={s.reportValue}>{Math.round(tripMinutes)} min</Text><Text style={s.metricLabel}>Tempo rastreado</Text></View><View style={s.reportCard}><Text style={s.reportKicker}>VISITAS</Text><Text style={s.reportValue}>{localVisits.length}</Text><Text style={s.metricLabel}>Movimentações locais</Text></View></View>
    <View style={s.reportWide}><Text style={s.reportWideTitle}>Dinheiro da operação</Text><Text style={s.reportWideSub}>Quanto estava previsto, quanto foi gasto e quanto pode precisar de reembolso.</Text><View style={s.reportLine}><Text style={s.sub}>Previsto na Agenda</Text><Text style={s.reportLineValue}>{money(agendaPlanned)}</Text></View><View style={s.reportLine}><Text style={s.sub}>Previsto em despesas</Text><Text style={s.reportLineValue}>{money(expenseSummary.planned)}</Text></View><View style={s.reportLine}><Text style={s.sub}>Realizado</Text><Text style={s.reportLineValue}>{money(expenseSummary.actual)}</Text></View><View style={s.reportLine}><Text style={s.sub}>Variação</Text><Text style={s.reportLineValue}>{expenseSummary.variance>0?'+':''}{money(expenseSummary.variance)}</Text></View><View style={s.reportLine}><Text style={s.sub}>Potencial a reembolsar</Text><Text style={s.reportLineValue}>{money(expenseSummary.reimbursement)}</Text></View><View style={s.reportLine}><Text style={s.sub}>Lançamentos</Text><Text style={s.reportLineValue}>{expenseSummary.count}</Text></View></View>
    {comparedTrips.length>0&&<View style={s.reportWide}><Text style={s.reportWideTitle}>Planejado × realizado</Text><Text style={s.reportWideSub}>Comparação das viagens planejadas que já possuem percurso GPS concluído.</Text><View style={s.reportLine}><Text style={s.sub}>KM planejado</Text><Text style={s.reportLineValue}>{plannedKm.toFixed(1)} km</Text></View><View style={s.reportLine}><Text style={s.sub}>KM realizado</Text><Text style={s.reportLineValue}>{actualComparedKm.toFixed(1)} km</Text></View><View style={s.reportLine}><Text style={s.sub}>Desvio de KM</Text><Text style={s.reportLineValue}>{distanceVarianceKm>=0?'+':''}{distanceVarianceKm.toFixed(1)} km</Text></View><View style={s.reportLine}><Text style={s.sub}>Paradas extras consideradas</Text><Text style={s.reportLineValue}>{extraStops}</Text></View><View style={s.reportLine}><Text style={s.sub}>Visitas extras confirmadas</Text><Text style={s.reportLineValue}>{confirmedExtraVisits}</Text></View><View style={s.reportLine}><Text style={s.sub}>Ocorrências de rota</Text><Text style={s.reportLineValue}>{routeOccurrences}</Text></View></View>}
    <View style={s.reportWide}><Text style={s.reportWideTitle}>Visão empresarial · últimos 30 dias</Text><Text style={s.reportWideSub}>Indicadores consolidados da base da empresa. Este bloco não depende do período escolhido acima.</Text><View style={s.reportLine}><Text style={s.sub}>Visitas</Text><Text style={s.reportLineValue}>{num(perf?.visits_30d)}</Text></View><View style={s.reportLine}><Text style={s.sub}>Visitas validadas</Text><Text style={s.reportLineValue}>{num(perf?.validated_visits_30d)}</Text></View><View style={s.reportLine}><Text style={s.sub}>KM remoto</Text><Text style={s.reportLineValue}>{num(perf?.actual_km_30d).toFixed(1)} km</Text></View><View style={s.reportLine}><Text style={s.sub}>Aderência</Text><Text style={s.reportLineValue}>{num(perf?.avg_adherence_pct).toFixed(0)}%</Text></View><View style={s.reportLine}><Text style={s.sub}>Pedidos</Text><Text style={s.reportLineValue}>{num(perf?.orders_30d)}</Text></View><View style={s.reportLine}><Text style={s.sub}>Receita</Text><Text style={s.reportLineValue}>{money(perf?.revenue_30d)}</Text></View></View>
    <View style={s.analysisCard}><Text style={s.reportWideTitle}>Leitura operacional</Text><Text style={s.analysisText}>{localTrips.length===0?'Sem deslocamentos registrados neste período.':'Há deslocamentos registrados no período selecionado.'}</Text><Text style={s.analysisText}>{localKmRecords.length===0?'Nenhum lançamento manual de KM neste período.':`${localKmRecords.length} lançamento(s) de KM somando ${localKm.toFixed(1)} km.`}</Text><Text style={s.analysisText}>{localVisits.length===0?'Nenhuma movimentação local de visita neste período.':`${localVisits.length} movimentação(ões) de visita registradas localmente.`}</Text></View>
    <Pressable style={s.primary} onPress={share}><Text style={s.primaryText}>Compartilhar visão gerencial</Text></Pressable>
    {!perf&&<Empty title="Indicadores remotos ainda indisponíveis" text="Os números locais continuam funcionando; a parte empresarial será preenchida quando a base liberar os indicadores."/>}
  </ScrollView>;
}

function NotificationCenter({ rows, onRead }: { rows: NotificationRow[]; onRead: (id: string) => Promise<void> }) {
  const [filter,setFilter] = useState<'all'|'unread'|'system'>('all');
  const visible = rows.filter(n => filter === 'unread' ? !n.read_at : filter === 'system' ? n.notification_type.toLowerCase().includes('system') || n.notification_type.toLowerCase().includes('sistema') : true);
  return <ScrollView contentContainerStyle={s.content} keyboardShouldPersistTaps="handled" automaticallyAdjustKeyboardInsets><View style={s.segment}><Pressable style={[s.segmentTab,filter==='all'&&s.segmentOn]} onPress={() => setFilter('all')}><Text style={[s.segmentText,filter==='all'&&s.segmentTextOn]}>Todas</Text></Pressable><Pressable style={[s.segmentTab,filter==='unread'&&s.segmentOn]} onPress={() => setFilter('unread')}><Text style={[s.segmentText,filter==='unread'&&s.segmentTextOn]}>Não lidas</Text></Pressable><Pressable style={[s.segmentTab,filter==='system'&&s.segmentOn]} onPress={() => setFilter('system')}><Text style={[s.segmentText,filter==='system'&&s.segmentTextOn]}>Sistema</Text></Pressable></View>{visible.length ? visible.map(n => <Pressable key={n.id} style={[s.notification,!n.read_at&&s.notificationUnread]} onPress={() => !n.read_at ? onRead(n.id) : undefined}><View style={[s.notifDot,n.priority==='high'&&{backgroundColor:RED}]}/><View style={{flex:1}}><Text style={s.rowTitle}>{n.title}</Text>{n.body ? <Text style={s.sub}>{n.body}</Text> : null}<Text style={s.notifTime}>{new Date(n.created_at).toLocaleString('pt-BR')}</Text></View>{!n.read_at&&<Text style={s.newText}>Nova</Text>}</Pressable>) : <Empty title="Nenhuma notificação" text="Não há itens neste filtro."/>}</ScrollView>;
}

function SyncPage({ online, pending, lastLoaded, errors, syncing, diagnostics, report, onSync, onRefresh }: { online: boolean; pending: number; lastLoaded?: string; errors: string[]; syncing: boolean; diagnostics: SyncDiagnostics; report: SyncReport | null; onSync: () => Promise<void>; onRefresh: () => Promise<void> }) {
  const rows:Array<[string,number,string]>=[['Visitas',diagnostics.visit,'Check-in e check-out'],['KM',diagnostics.km,'Odômetro e comprovantes'],['Rotas',diagnostics.trip,'Deslocamentos e GPS'],['Agenda',diagnostics.appointment,'Compromissos locais']];
  return <ScrollView contentContainerStyle={s.content} keyboardShouldPersistTaps="handled" automaticallyAdjustKeyboardInsets><View style={s.syncHero}><View style={[s.syncBig,!online&&{backgroundColor:'#FFF3E5'}]}><Text style={[s.syncBigText,!online&&{color:ORANGE}]}>{online?'✓':'!'}</Text></View><Text style={s.syncHeroTitle}>{online?'Central de sincronização':'Modo offline ativo'}</Text><Text style={s.syncHeroText}>{pending ? `${pending} alteração(ões) protegidas no aparelho e aguardando confirmação do servidor.` : 'Não há alterações locais pendentes.'}</Text></View><View style={s.syncGrid}>{rows.map(([label,value,sub])=><View key={label} style={s.syncDiagCard}><Text style={s.syncDiagValue}>{value}</Text><Text style={s.rowTitle}>{label}</Text><Text style={s.sub}>{sub}</Text></View>)}</View>{report&&<View style={s.reportWide}><Text style={s.rowTitle}>Última tentativa</Text><Text style={s.sub}>{new Date(report.attemptedAt).toLocaleString('pt-BR')} · {report.sent} enviado(s) · {report.pending} pendente(s)</Text>{report.issues.slice(0,4).map((i,idx)=><View key={`${i.entity}-${idx}`} style={s.syncIssue}><Text style={s.warningTitle}>{i.entity.toUpperCase()}</Text><Text style={s.warningText}>{i.message}</Text></View>)}</View>}<View style={s.checkRow}><Text style={s.check}>✓</Text><View><Text style={s.rowTitle}>Agenda, KM e deslocamentos</Text><Text style={s.sub}>Persistência local ativa</Text></View></View><View style={s.checkRow}><Text style={online?s.check:s.warn}>●</Text><View><Text style={s.rowTitle}>Base empresarial</Text><Text style={s.sub}>{lastLoaded ? `Última carga: ${new Date(lastLoaded).toLocaleString('pt-BR')}` : 'Ainda não carregada'}</Text></View></View><Pressable style={[s.primary,(!online||syncing)&&s.disabled]} onPress={onSync} disabled={!online||syncing}><Text style={s.primaryText}>{syncing?'Sincronizando...':'Enviar fila agora'}</Text></Pressable><Pressable style={[s.secondaryButton,(!online||syncing)&&s.disabled]} onPress={onRefresh} disabled={!online||syncing}><Text style={s.secondaryButtonText}>Atualizar dados empresariais</Text></Pressable>{errors.length > 0 && <View style={s.warningCard}><Text style={s.warningTitle}>Atenção na última carga</Text>{errors.slice(0,4).map((e,i)=><Text key={i} style={s.warningText}>• {e}</Text>)}</View>}</ScrollView>;
}

function Settings({ session, data, prefs, setPrefs, logout }: { session: Session; data: BootstrapData | null; prefs: Preferences; setPrefs: (p: Preferences) => void; logout: () => void }) {
  const name = nameOf(session,data);
  const favKey=`movvant.rc11.favoriteOrigins.${session.user.id}`;
  const [favoriteOrigins,setFavoriteOrigins]=useState<Array<{label:string,address:string}>>([{label:'Local principal',address:''},{label:'Local alternativo',address:''}]);
  useEffect(()=>{AsyncStorage.getItem(favKey).then(raw=>{try{const x=raw?JSON.parse(raw):[];if(Array.isArray(x)&&x.length)setFavoriteOrigins([{label:'Local principal',address:''},{label:'Local alternativo',address:''}].map((d,i)=>x[i]||d))}catch{}})},[favKey]);
  const saveFavorite=(i:number,address:string)=>{const next=favoriteOrigins.map((x,n)=>n===i?{...x,address}:x);setFavoriteOrigins(next);AsyncStorage.setItem(favKey,JSON.stringify(next));};
  const rows: Array<{title:string;sub:string;value:boolean;key:keyof Preferences}> = [
    { title:'Sincronização automática', sub:'Enviar a fila quando houver internet', value:prefs.autoSync, key:'autoSync' },
    { title:'Modo offline', sub:'Manter registros locais sem conexão', value:prefs.offlineMode, key:'offlineMode' },
    { title:'Notificações', sub:'Exibir alertas operacionais no app', value:prefs.notifications, key:'notifications' },
  ];
  const change = async (key: keyof Preferences, value: boolean) => { const next = { ...prefs, [key]: value }; setPrefs(next); await savePrefs(next); };
  return <ScrollView contentContainerStyle={s.content} keyboardShouldPersistTaps="handled" automaticallyAdjustKeyboardInsets><View style={s.profileCard}><View style={s.avatarBig}><Text style={s.avatarText}>{initials(name)}</Text></View><View style={{flex:1}}><Text style={s.profileName}>{name}</Text><Text style={s.sub}>{session.user.email||''}</Text><Text style={s.muted}>{roleOf(data)}{data?.directory?.branch_name?` · ${data.directory.branch_name}`:''}</Text></View></View><View style={s.aboutCard}><Text style={s.rowTitle}>Endereços favoritos de partida</Text><Text style={s.sub}>Aparecem antes da busca ao planejar uma viagem.</Text>{favoriteOrigins.map((x,i)=><View key={i} style={{marginTop:10}}><Text style={s.label}>{x.label}</Text><TextInput style={s.input} value={x.address} onChangeText={v=>saveFavorite(i,v)} placeholder="Digite um endereço"/></View>)}</View>{rows.map(r => <View style={s.setting} key={r.key}><View style={{flex:1}}><Text style={s.rowTitle}>{r.title}</Text><Text style={s.sub}>{r.sub}</Text></View><Switch value={r.value} onValueChange={v => change(r.key,v)}/></View>)}<View style={s.aboutCard}><Text style={s.rowTitle}>Movvant Enterprise</Text><Text style={s.sub}>Mobile RC11 Integrado · versão 1.1.1</Text><Text style={s.sub}>Dados locais protegidos e acesso autenticado.</Text></View><Pressable style={s.logout} onPress={logout}><Text style={s.logoutText}>Sair da conta</Text></Pressable></ScrollView>;
}

function More({ page, setPage, data, local, session, prefs, setPrefs, online, pending, syncing, diagnostics, syncReport, onSync, onRefresh, onRead, logout }: { page: MorePage; setPage: (p: MorePage) => void; data: BootstrapData | null; local: LocalState; session: Session; prefs: Preferences; setPrefs: (p: Preferences) => void; online: boolean; pending: number; syncing: boolean; diagnostics: SyncDiagnostics; syncReport: SyncReport | null; onSync: () => Promise<void>; onRefresh: () => Promise<void>; onRead: (id: string) => Promise<void>; logout: () => void }) {
  if (page === 'lojas') return <Stores customers={data?.customers || []} branchId={data?.branchId || null} branchScoped={data?.directory?.scope_level === 'branch'}/>;
  if (page === 'relatorios') return <Reports data={data} local={local}/>;
  if (page === 'despesas') return <ExpensesScreen companyId={data?.companyId} userId={session.user.id} vehicles={data?.vehicles || []} customers={data?.customers || []} appointments={local.appointments}/>;
  if (page === 'notificacoes') return <NotificationCenter rows={prefs.notifications ? (data?.notifications || []) : []} onRead={onRead}/>;
  if (page === 'sincronizacao') return <SyncPage online={online} pending={pending} lastLoaded={data?.loadedAt} errors={data?.errors || []} syncing={syncing} diagnostics={diagnostics} report={syncReport} onSync={onSync} onRefresh={onRefresh}/>;
  if (page === 'configuracoes') return <Settings session={session} data={data} prefs={prefs} setPrefs={setPrefs} logout={logout}/>;
  return <ScrollView contentContainerStyle={s.content} keyboardShouldPersistTaps="handled" automaticallyAdjustKeyboardInsets><Hero title="Operação completa" text="Acesse rapidamente os módulos do seu dia."/><Row icon="▦" title="Lojas" sub={`${data?.customers.length || 0} loja(s) disponíveis`} onPress={() => setPage('lojas')}/><Row icon="↗" title="Relatórios" sub="Indicadores reais da operação" onPress={() => setPage('relatorios')}/><Row icon="R$" title="Despesas & Prestação" sub="Gastos, comprovantes e reembolsos" onPress={() => setPage('despesas')}/><Row icon="↻" title="Sincronização" sub={pending ? `${pending} item(ns) pendente(s)` : online ? 'Tudo sincronizado' : 'Modo offline'} onPress={() => setPage('sincronizacao')}/><Row icon="●" title="Notificações" sub={`${(data?.notifications || []).filter(x => !x.read_at).length} não lida(s)`} onPress={() => setPage('notificacoes')}/><Row icon="⚙" title="Configurações" sub="Perfil, sessão e preferências" onPress={() => setPage('configuracoes')}/></ScrollView>;
}

function Drawer({ visible, close, setTab, setMore, session, data, logout }: { visible: boolean; close: () => void; setTab: (t: Tab) => void; setMore: (p: MorePage) => void; session: Session; data: BootstrapData | null; logout: () => void }) {
  if (!visible) return null;
  const go = (t: Tab,p?: MorePage) => { setTab(t); if (p) setMore(p); close(); };
  const name = nameOf(session,data);
  const entries: Array<[string,string,()=>void]> = [['⌂','Home',()=>go('home')],['▣','Agenda',()=>go('agenda')],['▦','Lojas',()=>go('mais','lojas')],['◎','KM',()=>go('km')],['⌖','Deslocamento',()=>go('mapa')],['↗','Relatórios',()=>go('mais','relatorios')],['R$','Despesas & Prestação',()=>go('mais','despesas')],['↻','Sincronização',()=>go('mais','sincronizacao')],['●','Notificações',()=>go('mais','notificacoes')],['⚙','Configurações',()=>go('mais','configuracoes')]];
  return <View style={s.drawerOverlay}><Pressable style={s.scrim} onPress={close}/><SafeAreaView style={s.drawer}><View style={s.drawerBrandRow}><View style={s.logoSmall}><Text style={s.logoSmallText}>M</Text></View><View><Text style={s.drawerBrand}>Movvant</Text><Text style={s.drawerEnt}>ENTERPRISE</Text></View></View><View style={s.drawerProfile}><View style={s.avatar}><Text style={s.avatarText}>{initials(name)}</Text></View><View><Text style={s.drawerName}>{name}</Text><Text style={s.drawerRole}>{roleOf(data)}</Text></View></View>{entries.map(([i,l,a]) => <Pressable key={l} style={s.drawerItem} onPress={a}><Text style={s.drawerItemIcon}>{i}</Text><Text style={s.drawerItemText}>{l}</Text></Pressable>)}<View style={{flex:1}}/><Pressable style={s.drawerExit} onPress={logout}><Text style={s.drawerExitText}>Sair</Text></Pressable></SafeAreaView></View>;
}

export default function AppRC11Final() {
  const [session,setSession] = useState<Session|null>(null); const [boot,setBoot] = useState(true); const [data,setData] = useState<BootstrapData|null>(null); const [local,setLocal] = useState<LocalState>({ appointments:[],km:[],trips:[],visits:[] }); const [online,setOnline] = useState(true); const [pending,setPending] = useState(0); const [syncing,setSyncing] = useState(false); const [prefs,setPrefs] = useState<Preferences>(DEFAULT_PREFS); const [enterpriseSettings,setEnterpriseSettings] = useState<EnterpriseSettings>(DEFAULT_ENTERPRISE_SETTINGS); const [diagnostics,setDiagnostics] = useState<SyncDiagnostics>({total:0,appointment:0,km:0,trip:0,visit:0,localOnlyAppointments:0}); const [syncReport,setSyncReport] = useState<SyncReport|null>(null); const [tab,setTab] = useState<Tab>('home'); const [more,setMore] = useState<MorePage>('menu'); const [drawer,setDrawer] = useState(false);
  const lastAutoSyncAttempt = useRef(0);

  const reloadLocal = useCallback(async () => { const [l,q,d,r]=await Promise.all([readLocalState(),readQueue(),readSyncDiagnostics(),readLastSyncReport()]); setLocal(l); setPending(q.length); setDiagnostics(d); setSyncReport(r); }, []);
  const refresh = useCallback(async (activeSession?: Session | null) => {
    const ss = activeSession || session; if (!ss) return;
    try { const remote = await loadBootstrap(ss); setData(remote); await saveBootstrap(ss.user.id,remote); } catch (e) { const cached = await readBootstrap(ss.user.id); if (cached) setData({ ...cached, errors:[...(cached.errors||[]),`Atualização: ${e instanceof Error ? e.message : 'sem conexão'}`] }); }
  }, [session]);
  const sync = useCallback(async () => {
    if (!session || !data?.companyId || !online || syncing) return;
    setSyncing(true);
    try { const result = await syncPending(session,data.companyId); await reloadLocal(); if (result.errors.length) Alert.alert('Sincronização parcial',`${result.sent} enviado(s), ${result.pending} pendente(s).`); }
    finally { setSyncing(false); }
  }, [session,data?.companyId,online,syncing,reloadLocal]);

  useEffect(() => {
    Promise.all([AsyncStorage.getItem(SESSION_KEY),readPrefs(),readLocalState(),readQueue(),NetInfo.fetch()]).then(async ([raw,p,l,q,net]) => {
      setPrefs(p); setLocal(l); setPending(q.length); setOnline(Boolean(net.isConnected));
      if (raw) {
        try {
          let ss = JSON.parse(raw) as Session;
          if (ss.refresh_token && ss.expires_at && ss.expires_at * 1000 < Date.now() + 60000 && net.isConnected) {
            try { ss = await refreshSession(ss); await AsyncStorage.setItem(SESSION_KEY,JSON.stringify(ss)); } catch {}
          }
          setSession(ss); const cached = await readBootstrap(ss.user.id); if (cached) setData(cached); if (net.isConnected) await refresh(ss);
        } catch { await AsyncStorage.removeItem(SESSION_KEY); }
      }
    }).finally(() => setBoot(false));
  }, []);

  useEffect(() => NetInfo.addEventListener(state => setOnline(Boolean(state.isConnected))), []);
  useEffect(() => { readEnterpriseSettings(data?.companyId).then(setEnterpriseSettings).catch(()=>setEnterpriseSettings(DEFAULT_ENTERPRISE_SETTINGS)); }, [data?.companyId]);
  useEffect(() => { if (!online || !prefs.autoSync || !enterpriseSettings.sync.autoSync || !session || !data?.companyId || pending <= 0 || syncing) return; const now = Date.now(); if (now - lastAutoSyncAttempt.current < Math.max(5000,enterpriseSettings.sync.retrySeconds*1000)) return; lastAutoSyncAttempt.current = now; sync(); }, [online,prefs.autoSync,enterpriseSettings.sync.autoSync,enterpriseSettings.sync.retrySeconds,session,data?.companyId,pending,syncing,sync]);

  const customersById = useMemo(() => new Map((data?.customers || []).map(c => [c.id,c])), [data?.customers]);
  const remoteAppointments = useMemo<Appointment[]>(() => (data?.visits || []).filter(v => v.scheduled_start).map(v => { const d = new Date(v.scheduled_start!); const c = customersById.get(v.customer_id); return { id:v.id,date:isoDate(d),time:`${pad(d.getHours())}:${pad(d.getMinutes())}`,title:v.purpose||'Visita',store:customerName(c),type:'Visita',customerId:v.customer_id,status:v.status }; }), [data?.visits,customersById]);
  const appointments = useMemo(() => [...remoteAppointments,...local.appointments.map(x => ({ ...x, local:!x.synced }))], [remoteAppointments,local.appointments]);
  const assignedVehicleIds = useMemo(() => new Set((data?.assignments || []).filter(a => !a.ends_at || new Date(a.ends_at).getTime() > Date.now()).map(a => a.vehicle_id)), [data?.assignments]);
  const assignedVehicles = useMemo(() => { const all = data?.vehicles || []; const scoped = all.filter(v => assignedVehicleIds.has(v.id)); return scoped.length ? scoped : all; }, [data?.vehicles,assignedVehicleIds]);

  const saveAppointment = async (item: LocalAppointment) => { await saveAppointmentLocal(item); await enqueueReplacingLocal('appointment',item.id,{ entity:'appointment',action:'insert',payload:{ localId:item.id,date:item.date,time:item.time,title:item.title,customerId:item.customerId,store:item.store } }); await reloadLocal(); };
  const saveTravelAppointment = async (item: LocalAppointment) => { await saveAppointmentLocal(item); await reloadLocal(); };
  const deleteAppointment = async (id: string) => { await removeAppointmentLocal(id); await removeQueuedForLocal('appointment',id); await reloadLocal(); };
  const saveKm = async (item: LocalKmRecord) => { await saveKmLocal(item); await enqueueReplacingLocal('km',item.id,{ entity:'km',action:'insert',payload:{ localId:item.id,vehicleId:item.vehicleId,vehicle:item.vehicle,start:item.start,end:item.end,total:item.total,reason:item.reason,photoUri:item.photoUri,createdAt:item.createdAt } }); await reloadLocal(); };
  const readNotification = async (id: string) => { if (!session || !online) return Alert.alert('Offline','Conecte-se para confirmar a leitura desta notificação.'); try { await markNotificationRead(session,id); setData(prev => prev ? { ...prev,notifications:prev.notifications.map(n => n.id===id?{...n,read_at:new Date().toISOString()}:n) } : prev); } catch (e) { Alert.alert('Notificação',e instanceof Error?e.message:'Não foi possível atualizar.'); } };
  const logout = async () => { await AsyncStorage.removeItem(SESSION_KEY); setSession(null); setData(null); setTab('home'); setMore('menu'); setDrawer(false); };
  const setMain = (t: Tab) => { setTab(t); if (t !== 'mais') setMore('menu'); };
  const doLogin = async (ss: Session) => { setSession(ss); setBoot(true); const cached = await readBootstrap(ss.user.id); if (cached) setData(cached); await reloadLocal(); await refresh(ss); setBoot(false); };

  if (boot) return <SafeAreaView style={s.boot}><Text style={s.bootBrand}>Movvant</Text><Text style={s.bootEnt}>ENTERPRISE</Text><Text style={s.bootSub}>Preparando sua operação...</Text></SafeAreaView>;
  if (!session) return <Login onLogin={doLogin}/>;

  const unread = prefs.notifications ? (data?.notifications || []).filter(x => !x.read_at).length : 0;
  const todayKey=isoDate(new Date());
  const plannedTravel=local.appointments.filter(x=>x.type==='Viagem'&&x.travel&&x.date===todayKey).sort((a,b)=>a.time.localeCompare(b.time))[0]||null;
  const normalizeRouteText=(v:string)=>v.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
  const plannedRouteText=plannedTravel?.travel?normalizeRouteText([plannedTravel.travel.origin,...plannedTravel.travel.stops,plannedTravel.travel.destination].join(' | ')):'';
  const plannedCustomerIds=(data?.customers||[]).filter(c=>{const names=[c.trade_name,c.legal_name].filter(Boolean).map(x=>normalizeRouteText(String(x)));return !!plannedRouteText&&names.some(n=>n.length>2&&plannedRouteText.includes(n));}).map(c=>c.id);
  const title = tab==='home'?'Movvant':tab==='agenda'?'Agenda':tab==='km'?'Controle de KM':tab==='mapa'?'Deslocamento':more==='lojas'?'Lojas':more==='relatorios'?'Relatórios':more==='despesas'?'Despesas & Prestação':more==='notificacoes'?'Notificações':more==='sincronizacao'?'Sincronização':more==='configuracoes'?'Configurações':'Mais';
  const back = tab === 'mais' && more !== 'menu' ? () => setMore('menu') : undefined;

  return <SafeAreaView style={s.screen}><StatusBar barStyle="light-content" backgroundColor={NAVY}/><Header title={title} onMenu={() => setDrawer(true)} onBack={back} unread={unread} onNotifications={()=>{setTab('mais');setMore('notificacoes')}}/><View style={s.body}>{tab==='home'&&<Home session={session} data={data} local={local} appointments={appointments} online={online} pending={pending} goAgenda={()=>setMain('agenda')} goMap={()=>setMain('mapa')}/>} {tab==='agenda'&&<Agenda appointments={appointments} customers={data?.customers||[]} userId={session.user.id} onSave={saveAppointment} onSaveTravel={saveTravelAppointment} onDelete={deleteAppointment}/>} {tab==='km'&&<Km vehicles={assignedVehicles} history={local.km} onSave={saveKm} companyId={data?.companyId}/>} {tab==='mapa'&&<RouteScreen onSaved={reloadLocal} companyId={data?.companyId} customers={data?.customers||[]} plannedCustomerIds={plannedCustomerIds} plannedTripId={plannedTravel?.id||null} plannedDistanceMeters={plannedTravel?.travel?.distanceMeters||0} plannedDurationSeconds={plannedTravel?.travel?.durationSeconds||0} plannedTollBRL={plannedTravel?.travel?.tollBRL||0}/>} {tab==='mais'&&<More page={more} setPage={setMore} data={data} local={local} session={session} prefs={prefs} setPrefs={setPrefs} online={online} pending={pending} syncing={syncing} diagnostics={diagnostics} syncReport={syncReport} onSync={sync} onRefresh={()=>refresh()} onRead={readNotification} logout={logout}/>}</View><Bottom tab={tab} setTab={(t)=>{if(t==='mais')setMore('menu');setMain(t)}}/><Drawer visible={drawer} close={()=>setDrawer(false)} setTab={setMain} setMore={setMore} session={session} data={data} logout={logout}/></SafeAreaView>;
}

